package com.shinpstudio.dailyoverlay;

import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;

public class OverlayService extends Service {
    static final String REFRESH="refresh", STOP="stop", PIN="pin";
    static volatile boolean running=false;
    final Handler ui=new Handler(Looper.getMainLooper()); final ExecutorService worker=Executors.newSingleThreadExecutor();
    WindowManager wm; SharedPreferences prefs; TextView bar; LinearLayout note,detail; WindowManager.LayoutParams noteLp; LocalDate selected=LocalDate.now(); boolean byApp=false; boolean fetching=false; ScrollView detailScroll; int generation=0;
    final Runnable tick=new Runnable(){public void run(){load();ui.postDelayed(this,30000);}};
    int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    @Override public IBinder onBind(Intent i){return null;}
    @Override public void onCreate(){super.onCreate();wm=getSystemService(WindowManager.class);prefs=UsageData.prefs(this);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("overlay","Daily Overlay",NotificationManager.IMPORTANCE_LOW));running=true;}
    @Override public int onStartCommand(Intent i,int flags,int id){String a=i==null?REFRESH:i.getAction();if(STOP.equals(a)){stopSelf();return START_NOT_STICKY;}if(PIN.equals(a))prefs.edit().putBoolean("pinned",!prefs.getBoolean("pinned",false)).apply();startForeground(1,notification());if(!Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}rebuild();ui.removeCallbacks(tick);ui.post(tick);return START_NOT_STICKY;}
    PendingIntent action(String a,int id){return PendingIntent.getService(this,id,new Intent(this,OverlayService.class).setAction(a),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
    Notification notification(){return new Notification.Builder(this,"overlay").setSmallIcon(com.shinpstudio.dailyoverlay.R.drawable.ic_overlay).setContentTitle("Daily Overlay").setContentText("利用時間とメモを表示中").setOngoing(true).setContentIntent(PendingIntent.getActivity(this,1,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).addAction(new Notification.Action.Builder(null,prefs.getBoolean("pinned",false)?"ピン解除":"ピン留め",action(PIN,2)).build()).addAction(new Notification.Action.Builder(null,"終了",action(STOP,3)).build()).build();}
    WindowManager.LayoutParams params(int w,int h,int flags){var p=new WindowManager.LayoutParams(w,h,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|flags,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;return p;}
    int width(){return wm.getCurrentWindowMetrics().getBounds().width();} int height(){return wm.getCurrentWindowMetrics().getBounds().height();}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
    void rebuild(){generation++;remove(detail);detail=null;detailScroll=null;remove(bar);bar=null;remove(note);note=null;
        if(prefs.getBoolean("showUsage",true)){bar=label("SNS —  ゲーム —  その他 —",prefs.getInt("usageText",11),Color.WHITE);bar.setGravity(Gravity.CENTER);bar.setSingleLine();bar.setPadding(dp(6),dp(2),dp(6),dp(2));bar.setBackground(bg(0xb52b3035,5));bar.setContentDescription("利用時間の詳細を開く");var p=params(-2,-2,0);p.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;p.y=dp(prefs.getInt("usageOffset",0));wm.addView(bar,p);bar.setOnClickListener(v->{if(detail==null)openDetail();else closeDetail();});}
        if(prefs.getBoolean("showNote",true))addNote();
    }
    void addNote(){boolean pin=prefs.getBoolean("pinned",false);int[] colors={0xffffe49a,0xffd2edcf,0xffcce8ff,0xfffafafa};int color=colors[Math.min(3,Math.max(0,prefs.getInt("noteColor",0)))];note=new LinearLayout(this);note.setOrientation(1);note.setBackground(bg(color,8));note.setPadding(dp(8),dp(4),dp(8),dp(6));
        if(!pin){LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);TextView drag=label("メモ  ・  移動",12,0xff5a513b);header.addView(drag,new LinearLayout.LayoutParams(0,dp(32),1));TextView edit=label("編集",12,0xff234c43);edit.setPadding(dp(5),0,dp(5),0);header.addView(edit);edit.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));TextView lock=label("固定",12,0xff234c43);lock.setPadding(dp(5),0,dp(5),0);header.addView(lock);lock.setOnClickListener(v->{prefs.edit().putBoolean("pinned",true).apply();rebuild();getSystemService(NotificationManager.class).notify(1,notification());load();});note.addView(header);drag.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int x,y;public boolean onTouch(View v,android.view.MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:sx=e.getRawX();sy=e.getRawY();x=noteLp.x;y=noteLp.y;return true;case MotionEvent.ACTION_MOVE:noteLp.x=Math.max(0,Math.min(width()-noteLp.width,x+(int)(e.getRawX()-sx)));noteLp.y=Math.max(minY(),Math.min(maxY(noteLp.height),y+(int)(e.getRawY()-sy)));wm.updateViewLayout(note,noteLp);return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:prefs.edit().putInt("noteX",noteLp.x).putInt("noteY",noteLp.y).apply();return true;}return false;}});}
        TextView content=label(prefs.getString("note","").isEmpty()?"メモなし":prefs.getString("note",""),prefs.getInt("noteText",16),0xff302c21);content.setGravity(Gravity.TOP);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.addView(content);note.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(!pin){TextView grip=label("↘",14,0xff5a513b);grip.setGravity(Gravity.RIGHT);note.addView(grip,new LinearLayout.LayoutParams(-1,dp(20)));grip.setOnTouchListener(new View.OnTouchListener(){float x,y;int w,h;public boolean onTouch(View v,MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:x=e.getRawX();y=e.getRawY();w=noteLp.width;h=noteLp.height;return true;case MotionEvent.ACTION_MOVE:noteLp.width=Math.max(dp(100),Math.min(Math.min(dp(340),width()-noteLp.x),w+(int)(e.getRawX()-x)));noteLp.height=Math.max(dp(70),Math.min(Math.min(dp(380),height()-noteLp.y-dp(72)),h+(int)(e.getRawY()-y)));wm.updateViewLayout(note,noteLp);return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:float d=getResources().getDisplayMetrics().density;prefs.edit().putInt("noteWidth",Math.round(noteLp.width/d)).putInt("noteHeight",Math.round(noteLp.height/d)).apply();return true;}return false;}});}
        noteLp=params(Math.min(width(),dp(prefs.getInt("noteWidth",180))),Math.min(dp(prefs.getInt("noteHeight",140)),Math.max(dp(70),height()-dp(100)-minY())),pin?WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE:0);noteLp.alpha=Math.min(.8f,prefs.getInt("noteAlpha",75)/100f);noteLp.x=Math.max(0,Math.min(width()-noteLp.width,prefs.getInt("noteX",width()-noteLp.width-dp(12))));noteLp.y=Math.max(minY(),Math.min(maxY(noteLp.height),prefs.getInt("noteY",dp(220))));wm.addView(note,noteLp);
    }
    int minY(){return bar==null?0:dp(prefs.getInt("usageOffset",0)+30);}int maxY(int h){return Math.max(minY(),height()-h-dp(72));}
    void openDetail(){generation++;selected=LocalDate.now();byApp=false;detail=new LinearLayout(this);detail.setOrientation(1);detail.setPadding(dp(12),dp(8),dp(12),dp(10));detail.setBackground(bg(0xfff9fafb,12));var p=params(Math.min(width()-dp(16),dp(420)),-2,0);p.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;p.y=dp(prefs.getInt("usageOffset",0)+30);wm.addView(detail,p);renderDetail(null);load();}
    void closeDetail(){remove(detail);detail=null;detailScroll=null;generation++;load();}
    void smallButton(LinearLayout row,String title,Runnable run){TextView t=label(title,14,0xff234c43);t.setGravity(Gravity.CENTER);t.setPadding(dp(8),0,dp(8),0);row.addView(t,new LinearLayout.LayoutParams(0,dp(42),1));t.setOnClickListener(v->run.run());}
    void renderDetail(UsageData.Snapshot data){if(detail==null)return;int oldScroll=detailScroll==null?0:detailScroll.getScrollY();detail.removeAllViews();LinearLayout dates=new LinearLayout(this);smallButton(dates,"＜",()->{selected=selected.minusDays(1);generation++;renderDetail(null);load();});TextView title=label(selected.toString(),14,Color.BLACK);title.setGravity(Gravity.CENTER);dates.addView(title,new LinearLayout.LayoutParams(0,dp(42),2));smallButton(dates,"＞",()->{if(selected.isBefore(LocalDate.now())){selected=selected.plusDays(1);generation++;renderDetail(null);load();}});smallButton(dates,"閉じる",this::closeDetail);detail.addView(dates);
        LinearLayout tabs=new LinearLayout(this);smallButton(tabs,byApp?"時間帯別":"● 時間帯別",()->{byApp=false;renderDetail(data);});smallButton(tabs,byApp?"● アプリ別":"アプリ別",()->{byApp=true;renderDetail(data);});detail.addView(tabs);
        ScrollView scroll=new ScrollView(this);detailScroll=scroll;LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);detail.addView(scroll,new LinearLayout.LayoutParams(-1,Math.min(dp(300),height()/2)));
        scroll.post(()->scroll.scrollTo(0,oldScroll));if(data==null){line(rows,"読み込み中…",Color.DKGRAY);return;}if(!data.permitted()){line(rows,"使用状況へのアクセスを許可してください",Color.DKGRAY);return;}
        long[] cats=data.categories();for(int i=0;i<3;i++)line(rows,UsageData.CATEGORIES[i]+"  "+UsageData.time(cats[i]),0xff234c43);if(data.sessions().isEmpty()){line(rows,"利用履歴がありません（OSの保持期間外の場合もあります）",Color.DKGRAY);return;}
        if(byApp){var totals=UsageEngine.totals(data.sessions());for(int i=0;i<3;i++){final int cat=i;line(rows,"— "+UsageData.CATEGORIES[i]+" —",0xff234c43);totals.entrySet().stream().filter(e->data.apps().get(e.getKey()).category()==cat).sorted((a,b)->Long.compare(b.getValue(),a.getValue())).forEach(e->line(rows,data.apps().get(e.getKey()).label()+"  "+UsageData.time(e.getValue()),Color.DKGRAY));}}
        else {DateTimeFormatter fmt=DateTimeFormatter.ofPattern("HH:mm");ZoneId z=ZoneId.systemDefault();for(var s:data.sessions()){var a=data.apps().get(s.pkg());String start=Instant.ofEpochMilli(s.start()).atZone(z).format(fmt),end=Instant.ofEpochMilli(s.end()).atZone(z).format(fmt);if(s.end()-s.start()<1000)continue;line(rows,start+"–"+end+"  "+a.label()+"  "+(s.duration()<60000?s.duration()/1000+"秒":UsageData.time(s.duration())),Color.DKGRAY);}}
    }
    void line(LinearLayout parent,String s,int color){TextView t=label(s,13,color);t.setPadding(0,dp(6),0,dp(6));parent.addView(t);}
    void load(){if(bar==null||fetching||!running)return;fetching=true;int g=generation;LocalDate day=LocalDate.now(), requested=selected;boolean details=detail!=null;worker.execute(()->{UsageData.Snapshot today=null,other=null;try{today=UsageData.read(this,day);other=details?(requested.equals(day)?today:UsageData.read(this,requested)):null;}catch(RuntimeException ignored){}final var t=today;final var o=other;ui.post(()->{fetching=false;if(!running)return;if(g!=generation){load();return;}if(bar!=null){if(t==null||!t.permitted())bar.setText("利用時間：権限を確認");else{long[] a=t.categories();bar.setText("SNS "+UsageData.shortTime(a[0])+"  ゲーム "+UsageData.shortTime(a[1])+"  その他 "+UsageData.shortTime(a[2]));}}if(detail!=null)renderDetail(o);});});}
    void remove(View v){if(v!=null)try{wm.removeView(v);}catch(IllegalArgumentException ignored){}}
    @Override public void onConfigurationChanged(Configuration c){super.onConfigurationChanged(c);if(running&&Settings.canDrawOverlays(this)){rebuild();load();}}
    @Override public void onDestroy(){running=false;ui.removeCallbacksAndMessages(null);worker.shutdownNow();remove(detail);remove(bar);remove(note);stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
